const API=process.env.API_URL||"http://localhost:3000",cache=new Map;async function fetchUser(e){const t=cache.get(e);if(t)return t.data;const r=await fetch(`${API}/users/${e}`);if(404===r.status)return null;if(!r.ok)throw new Error(`HTTP ${r.status}`);const s=await r.json();return cache.set(e,{data:s}),s}module.exports={fetchUser};
